// Kleene evaluation helpers
const V = {F:0, U:1, T:2};
function not(x){ return x===V.T?V.F: x===V.F?V.T: V.U; }
function or(x,y){ return Math.max(x,y); }
function and(x,y){ return Math.min(x,y); }
function imp(a,b){ return or(not(a), b); }

const A=V.U, B=V.F, C=V.U, D=V.T;
const c1 = imp(or(A, not(B)), and(C,D));
const c2 = or(not(C), and(A,B));
const c3 = imp(or(D, not(A)), not(B));
console.log([c1,c2,c3].map(v=> v===V.T?'T': v===V.U?'U':'F').join(' '));
```

